// The codes of the processing flow the app names. The source of truth is
// `assets/contract/processing-codes.json` (generated by the backend);
// `test/processing_codes_contract_test.dart` fails when a list here drifts
// from that file.

class ProcRecordKind {
  static const petition = 'PETITION';
  static const incident = 'INCIDENT';
  static const caseRecord = 'CASE';
  static const all = [petition, incident, caseRecord];
}

class ProcBand {
  static const overdue = 'OVERDUE';
  static const red = 'RED';
  static const yellow = 'YELLOW';
  static const green = 'GREEN';
  static const none = 'NONE';
  static const all = [overdue, red, yellow, green, none];

  /// The four bands that have a count on the tracking screens.
  static const counted = [overdue, red, yellow, green];
}

class ProcAlertSource {
  static const flow = 'FLOW';
  static const recordDeadline = 'RECORD_DEADLINE';
  static const all = [flow, recordDeadline];
}

class ProcStepStatus {
  static const waitingAnchor = 'WAITING_ANCHOR';
  static const open = 'OPEN';
  static const reported = 'REPORTED';
  static const done = 'DONE';
  static const skipped = 'SKIPPED';
  static const all = [waitingAnchor, open, reported, done, skipped];
}

class ProcPartyRole {
  static const main = 'MAIN';
  static const check = 'CHECK';
  static const coordinate = 'COORDINATE';
  static const inform = 'INFORM';
  static const all = [main, check, coordinate, inform];
}

class ProcReportKind {
  static const progress = 'PROGRESS';
  static const result = 'RESULT';
  static const all = [progress, result];
}

/// The error codes the app gives its own wording to. Every other code is
/// shown with a general sentence and the code itself.
class ProcError {
  static const revisionConflict = 'REVISION_CONFLICT';
  static const notAPartyOfStep = 'NOT_A_PARTY_OF_STEP';
  static const stepNotOpen = 'STEP_NOT_OPEN';
  static const stepNotReported = 'STEP_NOT_REPORTED';
  static const stepNeedsApproval = 'STEP_NEEDS_APPROVAL';
  static const stepTransitionInvalid = 'STEP_TRANSITION_INVALID';
  static const reportTextRequired = 'REPORT_TEXT_REQUIRED';
  static const noResultReport = 'NO_RESULT_REPORT';
  static const idempotencyKeyReused = 'IDEMPOTENCY_KEY_REUSED';
  static const recordFlowNotFound = 'RECORD_FLOW_NOT_FOUND';
  static const named = [
    revisionConflict,
    notAPartyOfStep,
    stepNotOpen,
    stepNotReported,
    stepNeedsApproval,
    stepTransitionInvalid,
    reportTextRequired,
    noResultReport,
    idempotencyKeyReused,
    recordFlowNotFound,
  ];
}
